-- =============================================================================
-- Lead Engine — the whole schema, in one file.
--
-- WHAT THIS IS
--
-- Every migration in supabase/migrations/, concatenated in filename order and
-- nothing else. It is GENERATED by scripts/build-schema.mjs, so it cannot drift
-- from what the application expects — the migrations remain the source of
-- truth. Change a migration, re-run that script, commit both.
--
-- HOW TO RUN IT
--
--   Supabase dashboard -> SQL Editor -> New query -> paste this whole file ->
--   Run. It takes a few seconds.
--
-- It assumes an EMPTY database — a fresh Supabase project, nothing created in
-- `public` yet. Running it twice will fail on the first `create table`, which is
-- the intended behaviour: this file builds a schema, it does not reconcile one.
--
-- BEFORE YOU RUN IT: enable pg_cron.
--
--   Dashboard -> Database -> Extensions -> search "pg_cron" -> enable.
--
-- The file asks for it too (`create extension if not exists pg_cron`), and in
-- the SQL editor you are `postgres`, so that usually succeeds on its own. But if
-- it does not, three scheduled jobs silently never get created — and those three
-- are the retention promises: Google-sourced search results and cached geocodes
-- expiring on their own, whether or not the app is deployed or awake. Near the
-- end this file asserts all three are scheduled and re-schedules any that are
-- missing, so a missing pg_cron surfaces as an error there rather than as a year
-- of data that quietly failed to expire.
--
-- AFTERWARDS, confirm the jobs exist:
--
--   select * from public.scheduled_jobs;
--
-- Three rows: expire-search-results (03:15 UTC), expire-geocode-cache (03:20)
-- and purge-deleted-leads (03:45). The fourth scheduled job — the nightly Google
-- refresh — is a Vercel cron rather than a database one, because it has to call
-- Google and Postgres cannot. See vercel.json and the README.
--
-- WHAT YOU GET
--
--   Transient side   searches, search_results
--   Permanent side   leads, lead_audits, lead_audit_findings, lead_scores,
--                    lead_notes, lead_activities, lead_refreshes,
--                    lists, lead_lists, saved_views
--   Cost control     api_usage, app_settings, geocode_cache
--   Read models      leads_library, lead_score_queue, lead_scoring_inputs,
--                    lead_facet_values, lead_status_counts, lead_list_counts,
--                    scheduled_jobs
--
-- A NOTE ON SECURITY, because it will look wrong in the advisor.
--
-- Every table has RLS enabled with NO policies, and USAGE on the `public` schema
-- is revoked from PUBLIC, `anon` and `authenticated`. That is deliberate and it
-- is the whole authorization model: sessions belong to NextAuth, so there is no
-- Supabase JWT and no auth.uid() for a policy to inspect. A leaked publishable
-- key fails at the schema, before it can name a table. `service_role` — what the
-- secret key resolves to — is granted explicitly and untouched.
--
-- Supabase's security advisor will report "RLS enabled, no policy" on every
-- table. Here that notice is the desired state, not a finding to fix.
-- =============================================================================


-- ============================================================================
-- 20260730180000_extensions_and_enums.sql
-- ============================================================================

-- Lead Engine — extensions, enums, shared trigger helpers.
--
-- Vocabulary policy: an enum is used only where the vocabulary is DECIDED.
-- Audit check codes and scoring factor keys are deliberately NOT enums — those
-- criteria are still open, and encoding them in the type system would force a
-- migration every time a check is added.

-- gen_random_uuid() is built into Postgres 13+; no pgcrypto needed.

-- Fuzzy name search inside the leads library ("search-within-leads" is
-- load-bearing per PRODUCT.md, and the library is expected to reach thousands).
-- Installed into `extensions` per Supabase convention, which also keeps the
-- security advisor from flagging an extension living in public.
create extension if not exists pg_trgm with schema extensions;

-- Lead lifecycle. Decided by the owner:
--   new -> researching -> contacted -> replied -> proposal -> won | lost | parked
create type public.lead_status as enum (
  'new',
  'researching',
  'contacted',
  'replied',
  'proposal',
  'won',
  'lost',
  'parked'
);

-- What the audit found at the front door. This is the one signal the whole
-- product is named after ("weak or MISSING web presence"), so it is a column,
-- not a finding.
create type public.website_status as enum (
  'no_website',   -- the business has no website at all
  'unreachable',  -- a URL exists but did not resolve / respond
  'reachable',    -- the site answered and was audited
  'error'         -- the audit itself failed; says nothing about the business
);

-- Finding weight. Kept coarse on purpose; the scoring config decides what each
-- level is worth, so the audit never bakes in a weighting.
create type public.audit_severity as enum ('critical', 'warning', 'info');

-- Outreach log vocabulary.
create type public.activity_type as enum (
  'call',
  'email',
  'message',
  'visit',
  'meeting',
  'status_change', -- written automatically when leads.status changes
  'other'
);

-- Touch updated_at on write.
-- search_path is pinned empty and every identifier is schema-qualified, which
-- is what keeps Supabase's security advisor quiet about mutable search paths.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

revoke all on function public.set_updated_at() from public, anon, authenticated;


-- ============================================================================
-- 20260730180100_transient_search.sql
-- ============================================================================

-- Lead Engine — TRANSIENT side of the split.
--
-- Nothing in this file is the owner's work product. `searches` is his own query
-- history and keeps forever; `search_results` holds Google-sourced Place data
-- and is deleted on a schedule. A row here is a candidate, never a lead.

-- ---------------------------------------------------------------------------
-- searches — query history. Contains no Google content, only what was asked.
-- ---------------------------------------------------------------------------
create table public.searches (
  id                 uuid primary key default gen_random_uuid(),

  -- what was asked
  query              text        not null,
  location_text      text,                       -- as typed, e.g. "Neuss, DE"
  location_lat       double precision,           -- resolved centre
  location_lng       double precision,
  radius_m           integer,
  category           text,                       -- Places type filter, if any

  -- how it went
  provider           text        not null default 'google_places',
  ran_at             timestamptz not null default now(),
  result_count       integer     not null default 0,
  estimated_cost_usd numeric(10, 4),             -- Places SKUs bill per request
  request_params     jsonb,                      -- exact params sent, for replay
  error              text,                       -- set when the call failed

  created_at         timestamptz not null default now(),

  constraint searches_radius_positive
    check (radius_m is null or radius_m > 0),
  constraint searches_result_count_non_negative
    check (result_count >= 0)
);

comment on table public.searches is
  'Query history. Transient by category but retained: it holds no Google content, only what the operator asked for.';

create index searches_ran_at_idx on public.searches (ran_at desc);

-- ---------------------------------------------------------------------------
-- search_results — Google Place payloads, on a clock.
--
-- Deliberately has NO pointer to leads. "Already saved?" is answered by joining
-- on google_place_id against the unique index on leads, which keeps the
-- transient side from holding a reference into the permanent side.
-- ---------------------------------------------------------------------------
create table public.search_results (
  id                uuid        primary key default gen_random_uuid(),
  search_id         uuid        not null references public.searches (id) on delete cascade,

  google_place_id   text        not null,        -- the one field Google lets us keep
  result_rank       integer,                     -- position within the result set

  -- volatile Google fields, valid only as of fetched_at
  name              text,
  formatted_address text,
  lat               double precision,
  lng               double precision,
  phone             text,
  website           text,
  rating            numeric(2, 1),
  user_rating_count integer,
  business_status   text,
  primary_type      text,
  types             text[],
  google_maps_uri   text,
  raw               jsonb,                       -- full Place payload as returned

  fetched_at        timestamptz not null default now(),
  expires_at        timestamptz not null default (now() + interval '30 days'),

  constraint search_results_unique_place_per_search
    unique (search_id, google_place_id),
  constraint search_results_rating_range
    check (rating is null or (rating >= 0 and rating <= 5)),
  constraint search_results_expiry_after_fetch
    check (expires_at > fetched_at)
);

comment on table public.search_results is
  'Volatile Google Places data with a hard expiry. A row here is a candidate, not a lead; the cleanup job deletes it and nothing is lost.';
comment on column public.search_results.expires_at is
  'Enforced by the scheduled cleanup job, not by Postgres. Default window: 30 days, the outer edge of Google''s caching guidance.';

create index search_results_search_id_rank_idx
  on public.search_results (search_id, result_rank);
create index search_results_expires_at_idx
  on public.search_results (expires_at);
create index search_results_google_place_id_idx
  on public.search_results (google_place_id);


-- ============================================================================
-- 20260730180200_permanent_leads.sql
-- ============================================================================

-- Lead Engine — PERMANENT side of the split.
--
-- Everything here survives indefinitely. Google-sourced columns on `leads` are a
-- snapshot carrying its own fetched_at and a refresh path; every other column is
-- the owner's own work product and never expires with it.

-- ---------------------------------------------------------------------------
-- leads — businesses explicitly saved. google_place_id is the identity.
-- ---------------------------------------------------------------------------
create table public.leads (
  id                  uuid primary key default gen_random_uuid(),

  -- identity: saving the same business from two searches updates one row.
  google_place_id     text        not null unique,

  -- ---- snapshot of Google data, valid only as of fetched_at ----------------
  name                text        not null,
  formatted_address   text,
  city                text,                       -- extracted for grouping/filtering
  region              text,
  postal_code         text,
  country_code        text,
  lat                 double precision,
  lng                 double precision,
  phone               text,
  website             text,
  rating              numeric(2, 1),
  user_rating_count   integer,
  business_status     text,
  primary_type        text,
  types               text[],
  google_maps_uri     text,
  place_snapshot      jsonb,
  fetched_at          timestamptz not null default now(),

  -- ---- the owner's own fields, which never expire -------------------------
  status              public.lead_status not null default 'new',
  follow_up_at        date,
  saved_at            timestamptz not null default now(),
  discovered_via_search_id uuid references public.searches (id) on delete set null,

  -- Denormalised pointers to the newest audit and score. Maintained by trigger,
  -- never written by the app. They exist so the leads list can sort and filter
  -- thousands of rows by score or audit outcome without a lateral join.
  current_score       smallint,
  current_score_id    uuid,
  scored_at           timestamptz,
  latest_audit_id     uuid,
  last_audited_at     timestamptz,

  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  constraint leads_rating_range
    check (rating is null or (rating >= 0 and rating <= 5))
);

comment on table public.leads is
  'Businesses the operator explicitly saved. Permanent. Google-sourced columns are a snapshot qualified by fetched_at; owner-authored columns outlive it.';
comment on column public.leads.fetched_at is
  'Age of the Google snapshot above it. Any surface showing those fields must be able to state this.';
comment on column public.leads.current_score is
  'Denormalised from the newest lead_scores row by trigger. Do not write directly.';

create index leads_status_idx           on public.leads (status);
create index leads_current_score_idx    on public.leads (current_score desc nulls last);
create index leads_saved_at_idx         on public.leads (saved_at desc);
create index leads_city_idx             on public.leads (city);
-- Partial: the Outreach queue only ever asks for leads that have a date set.
create index leads_follow_up_at_idx     on public.leads (follow_up_at)
  where follow_up_at is not null;
-- Fuzzy search-within-leads. The operator class is schema-qualified because
-- pg_trgm lives in `extensions`, which is not on every role's search_path.
create index leads_name_trgm_idx        on public.leads using gin (name extensions.gin_trgm_ops);

create trigger leads_set_updated_at
  before update on public.leads
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- lead_audits — one row per website audit run. History is the point: it is how
-- you see that someone finally fixed their site.
--
-- Hybrid model, and the rule that keeps the two halves from drifting:
--
--   COLUMNS here hold MEASUREMENTS  — what was observed, no judgement implied.
--   FINDINGS hold JUDGEMENTS        — whether something is a problem, how bad.
--
-- The two do not overlap, so there is nothing to keep in sync. The six columns
-- below are the signals worth sorting and filtering a thousand-row library on;
-- they are facts about a page, not criteria, so committing to them does not
-- pre-empt the weighting decision PRODUCT.md leaves open. Everything else that
-- a checker learns goes to lead_audit_findings, where new checks cost no
-- migration. All six are nullable: they are unknown unless the site answered.
-- ---------------------------------------------------------------------------
create table public.lead_audits (
  id                 uuid        primary key default gen_random_uuid(),
  lead_id            uuid        not null references public.leads (id) on delete cascade,

  audited_at         timestamptz not null default now(),
  checker_version    text        not null,        -- which auditor produced this
  website_url        text,                        -- the URL actually audited
  final_url          text,                        -- after redirects
  website_status     public.website_status not null,
  http_status        smallint,
  duration_ms        integer,                     -- how long the audit itself took
  error              text,                        -- set when website_status = 'error'

  -- ---- measured signals ---------------------------------------------------
  is_https             boolean,                   -- final_url served over TLS
  is_mobile_friendly   boolean,                   -- responsive viewport declared
  has_meta_description boolean,
  load_ms              integer,                   -- page load time, sortable
  copyright_year       smallint,                  -- footer year; the abandonment tell
  platform             text,                      -- detected CMS: wordpress, wix, none…

  raw                jsonb,                       -- full checker output

  created_at         timestamptz not null default now(),

  constraint lead_audits_copyright_year_plausible
    check (copyright_year is null or (copyright_year between 1990 and 2100)),
  constraint lead_audits_load_ms_non_negative
    check (load_ms is null or load_ms >= 0)
);

comment on table public.lead_audits is
  'Append-only audit history. checker_version keeps an old audit explainable after the auditor changes.';
comment on column public.lead_audits.platform is
  'Free text, not an enum: the set of detectable platforms grows with the checker.';

create index lead_audits_lead_id_audited_at_idx
  on public.lead_audits (lead_id, audited_at desc);
create index lead_audits_website_status_idx
  on public.lead_audits (website_status);

-- ---------------------------------------------------------------------------
-- lead_audit_findings — structured, filterable judgements. Not a text blob.
--
-- The open half of the hybrid. `code` is text, not an enum: the check
-- vocabulary is undecided, and adding a check must not require a migration.
-- Filtering leads by finding is
--   join lead_audit_findings f on f.audit_id = leads.latest_audit_id
--   where f.code = '...' and not f.passed
-- while filtering on a measured signal reads straight off lead_audits. Neither
-- duplicates the other.
-- ---------------------------------------------------------------------------
create table public.lead_audit_findings (
  id        bigint generated always as identity primary key,
  audit_id  uuid    not null references public.lead_audits (id) on delete cascade,

  code      text    not null,                     -- e.g. 'no_https', 'no_meta_description'
  category  text,                                 -- e.g. 'seo', 'mobile', 'trust'
  severity  public.audit_severity not null default 'info',
  passed    boolean not null,
  value     jsonb,                                -- supporting evidence, e.g. {"tags_missing": ["h1"]}
  message   text,                                 -- one-line human summary for the UI

  constraint lead_audit_findings_unique_code_per_audit
    unique (audit_id, code)
);

comment on table public.lead_audit_findings is
  'One row per judgement per audit. Findings are data, so new criteria need no schema change. Measured signals live on lead_audits instead.';

-- No standalone audit_id index: the unique constraint above already indexes
-- (audit_id, code) and serves lookups by audit on its own.
create index lead_audit_findings_code_idx on public.lead_audit_findings (code);
-- The only question the leads list asks: which checks did this site FAIL?
create index lead_audit_findings_failed_idx
  on public.lead_audit_findings (code, severity)
  where passed = false;

-- ---------------------------------------------------------------------------
-- lead_scores — score plus the breakdown that produced it, versioned by config.
-- ---------------------------------------------------------------------------
create table public.lead_scores (
  id             uuid        primary key default gen_random_uuid(),
  lead_id        uuid        not null references public.leads (id) on delete cascade,
  audit_id       uuid        references public.lead_audits (id) on delete set null,

  score          smallint    not null,
  config_version text        not null,            -- so old scores stay explainable
  factors        jsonb       not null,            -- [{key, label, weight, raw, contribution}]
  computed_at    timestamptz not null default now(),

  constraint lead_scores_score_range check (score >= 0 and score <= 100)
);

comment on table public.lead_scores is
  'Append-only. A score is never edited; a re-score is a new row, so history stays readable under an old config.';

create index lead_scores_lead_id_computed_at_idx
  on public.lead_scores (lead_id, computed_at desc);
create index lead_scores_config_version_idx
  on public.lead_scores (config_version);

-- Close the denormalisation loop now that both targets exist.
alter table public.leads
  add constraint leads_current_score_id_fkey
    foreign key (current_score_id) references public.lead_scores (id) on delete set null,
  add constraint leads_latest_audit_id_fkey
    foreign key (latest_audit_id) references public.lead_audits (id) on delete set null;

-- ---------------------------------------------------------------------------
-- lead_notes — freeform, timestamped.
-- ---------------------------------------------------------------------------
create table public.lead_notes (
  id         uuid        primary key default gen_random_uuid(),
  lead_id    uuid        not null references public.leads (id) on delete cascade,
  body       text        not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  constraint lead_notes_body_not_blank check (length(btrim(body)) > 0)
);

create index lead_notes_lead_id_created_at_idx
  on public.lead_notes (lead_id, created_at desc);

create trigger lead_notes_set_updated_at
  before update on public.lead_notes
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- lead_activities — the outreach log: what I did, when.
-- ---------------------------------------------------------------------------
create table public.lead_activities (
  id            bigint generated always as identity primary key,
  lead_id       uuid        not null references public.leads (id) on delete cascade,

  type          public.activity_type not null,
  occurred_at   timestamptz not null default now(),
  summary       text,

  -- populated on 'status_change' rows, written by trigger
  status_before public.lead_status,
  status_after  public.lead_status,

  created_at    timestamptz not null default now()
);

comment on table public.lead_activities is
  'Outreach log. Status transitions are appended automatically so a lead read cold two months later still explains itself.';

create index lead_activities_lead_id_occurred_at_idx
  on public.lead_activities (lead_id, occurred_at desc);
create index lead_activities_occurred_at_idx
  on public.lead_activities (occurred_at desc);

-- ---------------------------------------------------------------------------
-- lists / lead_lists — grouping by city, campaign, vertical.
-- ---------------------------------------------------------------------------
create table public.lists (
  id          uuid        primary key default gen_random_uuid(),
  name        text        not null,
  description text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),

  constraint lists_name_not_blank check (length(btrim(name)) > 0)
);

-- Case-insensitive uniqueness: "Neuss" and "neuss" are the same list.
create unique index lists_name_unique_idx on public.lists (lower(name));

create trigger lists_set_updated_at
  before update on public.lists
  for each row execute function public.set_updated_at();

create table public.lead_lists (
  list_id  uuid        not null references public.lists (id) on delete cascade,
  lead_id  uuid        not null references public.leads (id) on delete cascade,
  added_at timestamptz not null default now(),

  primary key (list_id, lead_id)
);

create index lead_lists_lead_id_idx on public.lead_lists (lead_id);

-- ---------------------------------------------------------------------------
-- Triggers that maintain the denormalised pointers on leads.
--
-- Both recompute from scratch rather than trusting NEW, so INSERT, UPDATE and
-- DELETE all converge on the truth.
-- ---------------------------------------------------------------------------
create or replace function public.refresh_lead_score_cache()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_lead_id uuid;
begin
  if tg_op = 'DELETE' then
    v_lead_id := old.lead_id;
  else
    v_lead_id := new.lead_id;
  end if;

  update public.leads l
     set current_score    = s.score,
         current_score_id = s.id,
         scored_at        = s.computed_at
    from (
      select id, score, computed_at
        from public.lead_scores
       where lead_id = v_lead_id
       order by computed_at desc, id desc
       limit 1
    ) s
   where l.id = v_lead_id;

  if not found then
    update public.leads
       set current_score = null, current_score_id = null, scored_at = null
     where id = v_lead_id;
  end if;

  return null;
end;
$$;

create trigger lead_scores_refresh_cache
  after insert or update or delete on public.lead_scores
  for each row execute function public.refresh_lead_score_cache();

create or replace function public.refresh_lead_audit_cache()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_lead_id uuid;
begin
  if tg_op = 'DELETE' then
    v_lead_id := old.lead_id;
  else
    v_lead_id := new.lead_id;
  end if;

  update public.leads l
     set latest_audit_id = a.id,
         last_audited_at = a.audited_at
    from (
      select id, audited_at
        from public.lead_audits
       where lead_id = v_lead_id
       order by audited_at desc, id desc
       limit 1
    ) a
   where l.id = v_lead_id;

  if not found then
    update public.leads
       set latest_audit_id = null, last_audited_at = null
     where id = v_lead_id;
  end if;

  return null;
end;
$$;

create trigger lead_audits_refresh_cache
  after insert or update or delete on public.lead_audits
  for each row execute function public.refresh_lead_audit_cache();

-- Status changes write themselves into the outreach log.
create or replace function public.log_lead_status_change()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.status is distinct from old.status then
    insert into public.lead_activities (lead_id, type, occurred_at, status_before, status_after)
    values (new.id, 'status_change', now(), old.status, new.status);
  end if;
  return new;
end;
$$;

create trigger leads_log_status_change
  after update of status on public.leads
  for each row execute function public.log_lead_status_change();

revoke all on function public.refresh_lead_score_cache()  from public, anon, authenticated;
revoke all on function public.refresh_lead_audit_cache()  from public, anon, authenticated;
revoke all on function public.log_lead_status_change()    from public, anon, authenticated;


-- ============================================================================
-- 20260730180300_lockdown.sql
-- ============================================================================

-- Lead Engine — deny-by-default lockdown.
--
-- Authorization for this app lives in the Next.js auth gate, not in Postgres:
-- NextAuth owns sessions, so there is no Supabase JWT and no auth.uid() for a
-- policy to inspect. Any auth.uid()-based policy here would match nothing and
-- only create the illusion of protection.
--
-- So the database's job is narrower and absolute: be unreachable by anyone but
-- the server. Three independent layers, any one of which would suffice:
--   1. RLS enabled with NO policies      -> zero rows visible to anon/authenticated
--   2. table privileges revoked          -> no access even if a policy appears
--   3. schema USAGE revoked              -> PostgREST cannot resolve the tables
-- The service role bypasses all three, and only the server holds that key.

alter table public.searches            enable row level security;
alter table public.search_results      enable row level security;
alter table public.leads               enable row level security;
alter table public.lead_audits         enable row level security;
alter table public.lead_audit_findings enable row level security;
alter table public.lead_scores         enable row level security;
alter table public.lead_notes          enable row level security;
alter table public.lead_activities     enable row level security;
alter table public.lists               enable row level security;
alter table public.lead_lists          enable row level security;

-- Intentionally no policies. Supabase's security advisor reports
-- "RLS enabled, no policy" as an informational notice; here that notice is the
-- desired state, not a finding to fix.

-- Layer 2 — privileges. Supabase's default privileges hand new public tables to
-- anon/authenticated, so revoking after the fact is not optional.
revoke all on all tables    in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;
revoke all on all functions in schema public from anon, authenticated;

alter default privileges in schema public revoke all on tables    from anon, authenticated;
alter default privileges in schema public revoke all on sequences from anon, authenticated;
alter default privileges in schema public revoke all on functions from anon, authenticated;

-- Layer 3 — the kill switch. Without USAGE on the schema, a leaked publishable
-- key cannot even name these tables.
--
-- The revoke from PUBLIC is the load-bearing half, and leaving it out is the
-- easy mistake: Postgres grants USAGE on `public` to the PUBLIC pseudo-role by
-- default, and every role inherits it. Revoking from `anon` and `authenticated`
-- alone removes their own grants and changes nothing, because the blanket grant
-- underneath is still there — `has_schema_privilege('anon','public','USAGE')`
-- keeps answering true and the layer is inert.
--
-- The two grants come first so the revoke cannot lock out the roles that have
-- to reach these tables. Both already hold on a Supabase project; restating them
-- makes this file correct on its own rather than dependent on what the platform
-- happened to set up.
grant usage on schema public to postgres, service_role;

revoke usage on schema public from public;
revoke usage on schema public from anon, authenticated;


-- ============================================================================
-- 20260730180400_expire_search_results.sql
-- ============================================================================

-- Lead Engine — the scheduled job that enforces the split.
--
-- Expiry runs in the database rather than in a Vercel cron so that the
-- compliance promise does not depend on the app being deployed, awake, or
-- reachable. If Lead Engine goes dark for a month, Google data still expires.
--
-- `searches` is deliberately NOT touched: it is the operator's own query
-- history and holds no Google content. Deleting results leaves the history row
-- intact, with its result_count preserved as a record of what was found.

create extension if not exists pg_cron;

create or replace function public.expire_search_results()
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_deleted integer;
begin
  delete from public.search_results where expires_at < now();
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;

revoke all on function public.expire_search_results() from public, anon, authenticated;

comment on function public.expire_search_results() is
  'Deletes Google-sourced search results past their retention window. Scheduled nightly via pg_cron.';

-- 03:15 UTC daily.
select cron.schedule(
  'expire-search-results',
  '15 3 * * *',
  $$select public.expire_search_results()$$
);


-- ============================================================================
-- 20260730190000_cost_control_and_caches.sql
-- ============================================================================

-- Lead Engine — cost control, and the caches that keep calls from repeating.
--
-- Cost control here is a hard stop, not a report. Three pieces:
--
--   api_usage      the ledger. One row per billable request, written whether
--                  the request succeeded or not, because Google bills a 500
--                  exactly like a 200. This is the only source of truth for
--                  "what have I spent" — the app never adds up its own guesses.
--   app_settings   the ceiling. One row, one number, checked before every call.
--   geocode_cache  a town centre does not move; paying to locate it twice is
--                  waste with no upside.
--
-- Plus `searches.params_hash`, which lets an identical search re-run inside the
-- retention window be answered from `search_results` for nothing at all.

-- ---------------------------------------------------------------------------
-- api_usage — the ledger.
--
-- Both amounts are stored. `list_amount_usd` is what the SKU costs;
-- `billed_amount_usd` is what survived the monthly free allowance. Keeping both
-- means the free tier running out is visible as a change in the second number
-- while the first stays flat, which is exactly the moment the operator needs to
-- notice. Recomputing that later from prices alone would be impossible once a
-- rate card changes.
-- ---------------------------------------------------------------------------
create table public.api_usage (
  id                bigint generated always as identity primary key,

  provider          text        not null,          -- 'google_places'
  sku               text        not null,          -- 'google_places.text_search.enterprise'
  units             integer     not null default 1,

  unit_price_usd    numeric(12, 6) not null,       -- list price per unit, as charged that day
  list_amount_usd   numeric(12, 6) not null,       -- units * unit_price_usd
  free_units        integer     not null default 0,-- units absorbed by the monthly allowance
  billed_amount_usd numeric(12, 6) not null,       -- what this actually costs

  search_id         uuid references public.searches (id) on delete set null,
  occurred_at       timestamptz not null default now(),

  -- Billing months are Google's, so UTC, not the operator's local month. Fixing
  -- the zone is what makes this expression immutable enough to be generated.
  billing_month     date generated always as
                      ((date_trunc('month', (occurred_at at time zone 'UTC')))::date) stored,

  constraint api_usage_units_positive       check (units > 0),
  constraint api_usage_free_units_in_range  check (free_units >= 0 and free_units <= units),
  constraint api_usage_amounts_non_negative check (list_amount_usd >= 0 and billed_amount_usd >= 0)
);

comment on table public.api_usage is
  'Every billable provider request, successful or not. The authoritative record of spend; the UI only ever reads sums from here.';
comment on column public.api_usage.billed_amount_usd is
  'List amount after the monthly free allowance. Diverges from list_amount_usd only once the allowance is exhausted.';

-- The two questions ever asked of this table: what has this month cost, and how
-- much of each SKU's free allowance is left.
create index api_usage_month_sku_idx  on public.api_usage (billing_month, sku);
create index api_usage_occurred_at_idx on public.api_usage (occurred_at desc);
create index api_usage_search_id_idx   on public.api_usage (search_id)
  where search_id is not null;

-- ---------------------------------------------------------------------------
-- app_settings — one row, enforced by the primary key.
--
-- `id boolean primary key check (id)` admits exactly one value, so a second row
-- is a constraint violation rather than a silent second configuration.
-- ---------------------------------------------------------------------------
create table public.app_settings (
  id                  boolean     primary key default true,
  -- Zero by choice, not as a placeholder: the default posture is free-tier only.
  -- The guard always authorises a call that costs nothing, so a $0 ceiling
  -- spends Google's 1,000 free Text Search calls a month — around 20,000
  -- businesses — and then stops dead rather than starting an invoice. Raising it
  -- is a deliberate act, which is the point.
  monthly_ceiling_usd numeric(10, 2) not null default 0.00,
  updated_at          timestamptz not null default now(),

  constraint app_settings_single_row     check (id),
  constraint app_settings_ceiling_positive check (monthly_ceiling_usd >= 0)
);

comment on table public.app_settings is
  'Single-row configuration. monthly_ceiling_usd is a hard stop: the server refuses billable calls once the month exceeds it.';

create trigger app_settings_set_updated_at
  before update on public.app_settings
  for each row execute function public.set_updated_at();

insert into public.app_settings (id) values (true);

-- ---------------------------------------------------------------------------
-- geocode_cache — typed location text to a point.
--
-- Expires at 30 days to stay inside Google's caching allowance for geocoding
-- results, the same window `search_results` uses. Keyed on the normalised query
-- so "Heilbronn", " heilbronn " and "HEILBRONN" are one cache entry.
-- ---------------------------------------------------------------------------
create table public.geocode_cache (
  query_norm        text        primary key,
  lat               double precision not null,
  lng               double precision not null,
  formatted_address text,
  provider          text        not null default 'google_places',
  fetched_at        timestamptz not null default now(),
  expires_at        timestamptz not null default (now() + interval '30 days'),

  constraint geocode_cache_expiry_after_fetch check (expires_at > fetched_at)
);

comment on table public.geocode_cache is
  'Resolved location text. Expires on the same 30-day clock as search_results — it is Google-sourced data like any other.';

create index geocode_cache_expires_at_idx on public.geocode_cache (expires_at);

-- ---------------------------------------------------------------------------
-- searches.params_hash — the key that makes a repeat search free.
--
-- Two searches with the same hash asked the same question. If the first one's
-- results have not expired yet, the second can be served from them without
-- touching Google. Nullable because history predating this column has no hash
-- and must not be resurrected as a false cache hit.
-- ---------------------------------------------------------------------------
alter table public.searches
  add column params_hash text;

comment on column public.searches.params_hash is
  'Stable hash of the normalised request. A later identical search replays this one''s results instead of paying again.';

create index searches_params_hash_ran_at_idx
  on public.searches (params_hash, ran_at desc)
  where params_hash is not null;

-- ---------------------------------------------------------------------------
-- Expiry for the new cache, on the same principle as search_results: it runs in
-- the database so the compliance promise does not depend on the app being up.
-- ---------------------------------------------------------------------------
create or replace function public.expire_geocode_cache()
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_deleted integer;
begin
  delete from public.geocode_cache where expires_at < now();
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;

revoke all on function public.expire_geocode_cache() from public, anon, authenticated;

comment on function public.expire_geocode_cache() is
  'Deletes Google-sourced geocoding results past their retention window. Scheduled nightly via pg_cron.';

-- 03:20 UTC, five minutes after the search-result sweep.
select cron.schedule(
  'expire-geocode-cache',
  '20 3 * * *',
  $$select public.expire_geocode_cache()$$
);

-- ---------------------------------------------------------------------------
-- Month-to-date spend, per SKU.
--
-- A function rather than a client-side sum because supabase-js cannot GROUP BY,
-- and because the free-allowance check runs before *every* billable call — it
-- has to be one indexed round trip, not a page of rows to add up in JavaScript.
-- ---------------------------------------------------------------------------
create or replace function public.api_usage_month_to_date(p_month date default null)
returns table (sku text, units bigint, list_usd numeric, billed_usd numeric)
language sql
stable
security invoker
set search_path = ''
as $$
  select u.sku,
         sum(u.units)::bigint            as units,
         sum(u.list_amount_usd)::numeric as list_usd,
         sum(u.billed_amount_usd)::numeric as billed_usd
    from public.api_usage u
   where u.billing_month = coalesce(
           p_month,
           (date_trunc('month', (now() at time zone 'UTC')))::date
         )
   group by u.sku;
$$;

revoke all on function public.api_usage_month_to_date(date) from public, anon, authenticated;

comment on function public.api_usage_month_to_date(date) is
  'Per-SKU spend for a billing month, defaulting to the current UTC month. Backs both the ceiling check and the running total in the UI.';

-- ---------------------------------------------------------------------------
-- Lockdown, extended to the new tables.
--
-- The ALTER DEFAULT PRIVILEGES from the original lockdown already keeps
-- anon/authenticated off anything created since, and schema USAGE is still
-- revoked. RLS is the one layer that must be switched on per table.
-- ---------------------------------------------------------------------------
alter table public.api_usage     enable row level security;
alter table public.app_settings  enable row level security;
alter table public.geocode_cache enable row level security;

-- Deliberately no policies, as before: only the service role reaches these.


-- ============================================================================
-- 20260730200000_saving_and_library.sql
-- ============================================================================

-- Lead Engine — what saving needs, and what the library needs to stay usable
-- once it holds thousands of rows.
--
-- Three additions, all on the permanent side:
--
--   1. Soft delete.  The operator will misclick. A delete therefore hides a row
--      and starts a clock; it does not destroy work product.
--   2. Enrichment state.  Saving kicks off an audit in the background, so the
--      library must be able to say "queued", "running" and "failed" as distinct
--      things from "never audited" (last_audited_at is null in all four cases).
--   3. Saved views.  A named filter set the operator returns to. Stored as the
--      filter state itself, not as SQL, so a view survives changes to how the
--      query is built.

-- ---------------------------------------------------------------------------
-- Enrichment lifecycle.
--
-- An enum, unlike the audit check codes: this vocabulary is closed and mine.
-- It describes the job, not the findings, so nothing here pre-empts the audit
-- criteria PRODUCT.md leaves open.
-- ---------------------------------------------------------------------------
create type public.enrichment_state as enum (
  'queued',   -- saved, waiting for the background pass
  'running',  -- the pass has it
  'done',     -- an audit row was written; see latest_audit_id
  'failed'    -- the pass itself broke. Says nothing about the business.
);

-- ---------------------------------------------------------------------------
-- leads — soft delete and enrichment tracking.
-- ---------------------------------------------------------------------------
alter table public.leads
  add column deleted_at            timestamptz,
  add column enrichment_state      public.enrichment_state,
  add column enrichment_queued_at  timestamptz,
  add column enrichment_started_at timestamptz,
  -- Kept separate from lead_audits.error: that column explains a site that did
  -- not answer, this one explains a run that never got far enough to say.
  add column enrichment_error      text;

comment on column public.leads.deleted_at is
  'Soft delete. Set means hidden from the library and free to be re-saved; the purge job removes the row for good after the undo window.';
comment on column public.leads.enrichment_state is
  'Lifecycle of the background audit pass, not its verdict. Null means never queued.';

-- Every list query in the library ends in `deleted_at is null`, so the indexes
-- that serve it are rebuilt partial. Smaller, and Postgres can use them without
-- rechecking the predicate.
drop index public.leads_status_idx;
drop index public.leads_current_score_idx;
drop index public.leads_saved_at_idx;
drop index public.leads_city_idx;
drop index public.leads_follow_up_at_idx;

create index leads_status_idx on public.leads (status)
  where deleted_at is null;
-- The library's default order. `nulls last` matches the query: an unscored lead
-- is unranked, not worst.
create index leads_current_score_idx on public.leads (current_score desc nulls last)
  where deleted_at is null;
create index leads_saved_at_idx on public.leads (saved_at desc)
  where deleted_at is null;
create index leads_city_idx on public.leads (city)
  where deleted_at is null;
create index leads_follow_up_at_idx on public.leads (follow_up_at)
  where deleted_at is null and follow_up_at is not null;

-- The undo affordance and the purge job both ask the same question.
create index leads_deleted_at_idx on public.leads (deleted_at)
  where deleted_at is not null;

-- The background pass claims work with this.
create index leads_enrichment_state_idx on public.leads (enrichment_state, enrichment_queued_at)
  where enrichment_state in ('queued', 'running');

-- ---------------------------------------------------------------------------
-- saved_views — a named filter set.
--
-- `filters` holds the same shape the URL carries, so a view is applied by
-- writing it into the query string and nothing else has to understand it. The
-- alternative — storing SQL — would rot the first time a filter is renamed.
-- ---------------------------------------------------------------------------
create table public.saved_views (
  id           uuid        primary key default gen_random_uuid(),
  name         text        not null,
  filters      jsonb       not null,
  position     integer     not null default 0,
  last_used_at timestamptz,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),

  constraint saved_views_name_not_blank check (length(btrim(name)) > 0),
  constraint saved_views_filters_is_object check (jsonb_typeof(filters) = 'object')
);

comment on table public.saved_views is
  'Named filter sets for the leads library. Stores the filter state, not SQL, so a view outlives the query builder.';

create unique index saved_views_name_unique_idx on public.saved_views (lower(name));
create index saved_views_position_idx on public.saved_views (position, created_at);

create trigger saved_views_set_updated_at
  before update on public.saved_views
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------------------
-- leads_library — the library's read model.
--
-- Every filter the operator can apply becomes a top-level column here: the
-- newest audit's measurements are lifted onto the lead, and list membership is
-- folded into an array he can be matched against with a single overlap test.
--
-- The reason is not tidiness. Filtering through a joined table means the query
-- layer has to reach into a related resource, and combining several such
-- filters with OR — "no HTTPS *or* not mobile-friendly" — stops being
-- expressible. Flattening first makes the whole filter set ordinary predicates
-- on one relation, which is also what lets the partial indexes above serve it.
--
-- Deliberately NOT here: place_snapshot and raw. They are large, and no list
-- view has ever needed them.
-- ---------------------------------------------------------------------------
create view public.leads_library
with (security_invoker = on) as
select
  l.id,
  l.google_place_id,
  l.name,
  l.formatted_address,
  l.city,
  l.region,
  l.postal_code,
  l.country_code,
  l.phone,
  l.website,
  l.rating,
  l.user_rating_count,
  l.business_status,
  l.primary_type,
  l.google_maps_uri,
  l.fetched_at,

  l.status,
  l.follow_up_at,
  l.saved_at,
  l.deleted_at,
  l.current_score,
  l.scored_at,
  l.latest_audit_id,
  l.last_audited_at,
  l.enrichment_state,
  l.enrichment_error,

  -- The newest audit's measurements, lifted. Null throughout when a lead has
  -- never been audited, which is a distinct filter from any of the faults.
  a.website_status,
  a.is_https,
  a.is_mobile_friendly,
  a.has_meta_description,
  a.load_ms,
  a.copyright_year,
  a.platform,

  ll.list_ids,
  coalesce(n.note_count, 0) as note_count
from public.leads l
  left join public.lead_audits a on a.id = l.latest_audit_id
  left join lateral (
    select coalesce(array_agg(x.list_id), '{}'::uuid[]) as list_ids
      from public.lead_lists x
     where x.lead_id = l.id
  ) ll on true
  left join lateral (
    select count(*) as note_count
      from public.lead_notes x
     where x.lead_id = l.id
  ) n on true;

comment on view public.leads_library is
  'Read model for the leads list: lead plus its newest audit measurements plus list membership, so every filter is a predicate on one relation.';

revoke all on public.leads_library from anon, authenticated;

-- ---------------------------------------------------------------------------
-- The purge job — the far end of the undo window.
--
-- In the database rather than a Vercel cron, for the same reason expiry is:
-- a promise that only holds while the app is awake is not a promise. Thirty
-- days is deliberately generous. This is the operator's own work product, not
-- Google's data, so the only clock on it is his own second thoughts.
-- ---------------------------------------------------------------------------
create or replace function public.purge_deleted_leads(p_older_than interval default interval '30 days')
returns integer
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_deleted integer;
begin
  delete from public.leads
   where deleted_at is not null
     and deleted_at < now() - p_older_than;
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;
$$;

revoke all on function public.purge_deleted_leads(interval) from public, anon, authenticated;

comment on function public.purge_deleted_leads(interval) is
  'Removes soft-deleted leads past the undo window, cascading their audits, scores, notes and activities. Scheduled nightly.';

-- 03:45 UTC daily, half an hour after the search-results sweep so the two never
-- contend for the same lock.
select cron.schedule(
  'purge-deleted-leads',
  '45 3 * * *',
  $$select public.purge_deleted_leads()$$
);

-- ---------------------------------------------------------------------------
-- Lockdown, extended to the new table. Same three layers as everything else:
-- the app's auth gate is the only authorization there is.
-- ---------------------------------------------------------------------------
alter table public.saved_views enable row level security;

revoke all on public.saved_views from anon, authenticated;


-- ============================================================================
-- 20260730210000_enrichment_pipeline.sql
-- ============================================================================

-- Lead Engine — what a full diagnosis needs.
--
-- The audit up to now measured six things at the front door. This widens it to
-- everything the operator asked to be able to say on a cold call, and adds the
-- judgement half that was deliberately left empty when the schema was drawn:
-- `lead_audit_findings` finally gets written to.
--
-- The rule from the original migration still holds and is the reason this is
-- mostly new COLUMNS plus one array:
--
--   COLUMNS on lead_audits hold MEASUREMENTS  — what was observed.
--   FINDINGS hold JUDGEMENTS                  — whether it is a problem, how bad.
--
-- A measurement earns a column when it carries a value worth showing as proof
-- ("PageSpeed 23", "certificate expired in 2021", "WordPress 4.9") or when it
-- is the headline fact about a business. Everything that is merely a verdict
-- stays a finding, where adding a check still costs no migration.

-- ---------------------------------------------------------------------------
-- PageSpeed runs as its own stage, so it gets its own job state.
--
-- An enum, by the same test the enrichment lifecycle passed: this vocabulary is
-- closed and mine. It describes a job, not a verdict, so nothing here pre-empts
-- the criteria.
--
-- 'skipped' rather than null is the default because it is the truth for every
-- audit written before this migration and for every lead with no site to profile.
-- ---------------------------------------------------------------------------
create type public.psi_state as enum (
  'pending',  -- the fast pass finished; PageSpeed has not run yet
  'running',  -- an invocation has claimed it
  'ok',       -- scores below are real
  'failed',   -- PageSpeed was asked and could not answer; see psi_error
  'skipped'   -- never asked: no website, not a real site, or it did not answer
);

-- ---------------------------------------------------------------------------
-- lead_audits — the widened measurement set.
-- ---------------------------------------------------------------------------
alter table public.lead_audits
  -- Availability. Two different businesses hide behind one "unreachable":
  -- a domain that no longer resolves (they let it lapse) and a server that
  -- refused (it is misconfigured). The first is the better sales call, so it
  -- is worth being able to tell them apart.
  add column dns_resolves     boolean,

  -- Trust. Separate from is_https, which only says the final URL had an https
  -- scheme. A site can serve https with a certificate that expired two years
  -- ago, and that is a stronger argument than not having one at all.
  add column tls_valid        boolean,
  add column tls_expires_at   timestamptz,

  -- Markup, measured. has_meta_description already lived here; these three are
  -- the same kind of one-bit observation and belong beside it.
  add column has_title        boolean,
  add column has_favicon      boolean,
  add column is_table_layout  boolean,

  -- The version string as found, never as judged. '4.9' is the evidence; that
  -- 4.9 is ancient is a finding.
  add column platform_version text,

  -- What the "website" actually is: a real site, or a Facebook page, or a
  -- Linktree. Free text for the same reason platform is — the set grows with
  -- the checker.
  add column presence_kind    text,

  -- PageSpeed Insights, lab data, mobile strategy.
  add column psi_state        public.psi_state not null default 'skipped',
  add column psi_performance  smallint,
  add column psi_lcp_ms       integer,
  add column psi_cls          numeric(5, 3),
  add column psi_error        text,
  -- When the stage last acted on this row: set on claim, overwritten on
  -- completion. One column rather than two, because the only question ever
  -- asked of it is "has this been sitting in `running` too long".
  add column psi_checked_at   timestamptz,

  -- Denormalised from lead_audit_findings by trigger. See below.
  add column failed_codes     text[] not null default '{}',

  add constraint lead_audits_psi_performance_range
    check (psi_performance is null or (psi_performance between 0 and 100)),
  add constraint lead_audits_psi_lcp_non_negative
    check (psi_lcp_ms is null or psi_lcp_ms >= 0),
  add constraint lead_audits_psi_cls_non_negative
    check (psi_cls is null or psi_cls >= 0);

comment on column public.lead_audits.dns_resolves is
  'Did the hostname resolve at all. Separates a lapsed domain from a broken server; both read as unreachable otherwise.';
comment on column public.lead_audits.tls_valid is
  'Did the certificate verify. Null means https was never successfully negotiated, which is not the same as an invalid certificate.';
comment on column public.lead_audits.presence_kind is
  'What the stored website really is: site, facebook, instagram, linktree, google_business, directory. Free text, like platform.';
comment on column public.lead_audits.psi_state is
  'Lifecycle of the PageSpeed stage, not its verdict. It runs after the audit row exists, so a lead has a diagnosis before its scores arrive.';
comment on column public.lead_audits.failed_codes is
  'Codes of this audit''s failed findings, maintained by trigger. Do not write directly.';

-- The PageSpeed stage claims work with this, and reclaims abandoned work with
-- the same index — hence both live states, not just 'pending'.
create index lead_audits_psi_queue_idx on public.lead_audits (psi_state, audited_at)
  where psi_state in ('pending', 'running');

-- ---------------------------------------------------------------------------
-- failed_codes — findings, folded back onto the audit so the library can filter
-- on them with one predicate.
--
-- Without this, "no HTTPS *or* not mobile-friendly" would have to reach through
-- lead_audit_findings, and the leads_library view exists precisely so that no
-- filter has to. Folding the codes onto the audit keeps every audit filter an
-- ordinary predicate on one relation, which is the whole design of that view.
--
-- Append-only is what makes a statement-level INSERT trigger sufficient: a
-- re-audit writes a NEW audit row with new findings, and a finding is never
-- edited. Deletes are not handled on purpose — findings only disappear when
-- their audit is cascade-deleted, and updating a row that is being deleted in
-- the same statement would be a footgun for no benefit.
-- ---------------------------------------------------------------------------
create or replace function public.refresh_audit_failed_codes()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  -- Recomputed from the full finding set rather than from the inserted rows,
  -- so the PageSpeed stage appending its findings later converges on the truth
  -- instead of overwriting what the fast pass found.
  update public.lead_audits a
     set failed_codes = coalesce(agg.codes, '{}'::text[])
    from (
      select f.audit_id,
             array_agg(f.code order by f.severity, f.code)
               filter (where not f.passed) as codes
        from public.lead_audit_findings f
       where f.audit_id in (select distinct audit_id from new_findings)
       group by f.audit_id
    ) agg
   where a.id = agg.audit_id;

  return null;
end;
$$;

revoke all on function public.refresh_audit_failed_codes() from public, anon, authenticated;

create trigger lead_audit_findings_refresh_codes
  after insert on public.lead_audit_findings
  referencing new table as new_findings
  for each statement execute function public.refresh_audit_failed_codes();

-- ---------------------------------------------------------------------------
-- leads_library — rebuilt on the widened audit.
--
-- Replaced rather than altered: the new measurements belong beside the ones
-- they extend, not appended after note_count where nobody would look for them.
--
-- `audit_flags` is the one addition that is not a straight lift. It is the
-- audit filter set, as an array: the failed finding codes, or the single
-- synthetic flag 'never_audited' when there is no audit to have findings. That
-- synthesis is deliberate — it collapses every audit filter, including the
-- absence of an audit, into a single overlap test, so the query layer never has
-- to OR an array predicate against a null check.
--
-- The cost is that the CASE puts this out of reach of an index on
-- lead_audits.failed_codes. At the stated scale — thousands of leads, one
-- operator — that is a hash join over a few thousand rows, and the view already
-- carries two lateral aggregates per row for the same reason. No index is added
-- for it, because one that cannot be used is worse than none.
-- ---------------------------------------------------------------------------
drop view public.leads_library;

create view public.leads_library
with (security_invoker = on) as
select
  l.id,
  l.google_place_id,
  l.name,
  l.formatted_address,
  l.city,
  l.region,
  l.postal_code,
  l.country_code,
  l.phone,
  l.website,
  l.rating,
  l.user_rating_count,
  l.business_status,
  l.primary_type,
  l.google_maps_uri,
  l.fetched_at,

  l.status,
  l.follow_up_at,
  l.saved_at,
  l.deleted_at,
  l.current_score,
  l.scored_at,
  l.latest_audit_id,
  l.last_audited_at,
  l.enrichment_state,
  l.enrichment_error,

  -- The newest audit's measurements, lifted. Null throughout when a lead has
  -- never been audited, which is a distinct filter from any of the faults.
  a.website_status,
  a.dns_resolves,
  a.is_https,
  a.tls_valid,
  a.tls_expires_at,
  a.is_mobile_friendly,
  a.has_title,
  a.has_meta_description,
  a.has_favicon,
  a.is_table_layout,
  a.load_ms,
  a.copyright_year,
  a.platform,
  a.platform_version,
  a.presence_kind,
  a.psi_state,
  a.psi_performance,
  a.psi_lcp_ms,
  a.psi_cls,

  case
    when l.latest_audit_id is null then array['never_audited']::text[]
    else coalesce(a.failed_codes, '{}'::text[])
  end as audit_flags,

  ll.list_ids,
  coalesce(n.note_count, 0) as note_count
from public.leads l
  left join public.lead_audits a on a.id = l.latest_audit_id
  left join lateral (
    select coalesce(array_agg(x.list_id), '{}'::uuid[]) as list_ids
      from public.lead_lists x
     where x.lead_id = l.id
  ) ll on true
  left join lateral (
    select count(*) as note_count
      from public.lead_notes x
     where x.lead_id = l.id
  ) n on true;

comment on view public.leads_library is
  'Read model for the leads list: lead plus its newest audit measurements plus list membership, so every filter is a predicate on one relation.';
comment on column public.leads_library.audit_flags is
  'Every audit filter as one array: failed finding codes, or [never_audited] when the lead has no audit. Match with overlap.';

revoke all on public.leads_library from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Re-audit everything.
--
-- Every audit written before this migration predates findings entirely: it has
-- no diagnosis attached and every column added above is null on it. Left alone,
-- such a row renders as "nothing found" — which is the single thing it does not
-- mean, and exactly the kind of quiet wrongness that gets read aloud on a call.
--
-- So every live lead goes back in the queue. The pass drains it in slices the
-- next time the library is opened. The old audit rows are not touched: history
-- is the point of keeping them, and a re-audit has always been a new row rather
-- than an edit of an old one.
-- ---------------------------------------------------------------------------
update public.leads
   set enrichment_state      = 'queued',
       enrichment_queued_at  = now(),
       enrichment_started_at = null,
       enrichment_error      = null
 where deleted_at is null;


-- ============================================================================
-- 20260730220000_scoring.sql
-- ============================================================================

-- Lead Engine — what the scorer needs from the schema, which is very little.
--
-- The table it writes to already exists: `lead_scores` was drawn with the score,
-- the config version and a jsonb breakdown from the start, and the trigger that
-- denormalises the newest row onto `leads.current_score` has been in place since
-- the same migration. So this adds no storage. It relaxes one constraint that
-- turned out to be wrong, and adds two work-list views — one per pass — for the
-- one question the application cannot ask PostgREST in a single round trip.

-- ---------------------------------------------------------------------------
-- A score may be absent, and absent is not zero.
--
-- Some businesses are deliberately taken out of the ranking rather than ranked
-- badly: permanently closed, or not one review on Google. They are not weak
-- leads, they are not leads, and the operator asked for them to score null.
--
-- NOT NULL made that impossible to express. The only other way to keep them
-- from ranking would have been to write no score row at all — which loses the
-- reason, and worse, leaves a lead that WAS scored before it closed sitting at
-- its old 90 for ever, first in the list, permanently closed.
--
-- So the row is still written, `score` is null, and `factors` carries the rule
-- that withheld it. The denormalisation trigger already copies the newest row's
-- score verbatim, so a null lands on `leads.current_score` and the lead sinks —
-- and every surface already distinguishes a null score from a zero one, because
-- "not scored yet" needed that distinction first.
--
-- The range check is untouched: a CHECK passes on null, so it still constrains
-- every score that exists.
-- ---------------------------------------------------------------------------
alter table public.lead_scores alter column score drop not null;

comment on column public.lead_scores.score is
  '0-100, or null when the business is deliberately excluded from ranking. Never zero for absence — zero means audited and nothing found.';
comment on column public.lead_scores.factors is
  'The full breakdown that produced the score: every fault with its points, the business-signal tier, and the exclusion rule when there is one. Written so an old score stays explainable under a config that has since changed.';

-- ---------------------------------------------------------------------------
-- lead_score_queue — which leads need scoring, as one predicate.
--
-- Scoring is free once the findings are stored, but knowing WHICH leads to
-- score is a comparison between two tables that PostgREST cannot express: the
-- newest score's audit against the lead's newest audit. Doing it in the client
-- would mean reading every lead and every score on every pass.
--
-- Three rules are built into the WHERE clause, and each is load-bearing:
--
--   1. Nothing is scored while PageSpeed is still running. Those findings
--      append to the SAME audit a stage later, so a score computed before they
--      land would be computed on half a diagnosis — and then look settled.
--   2. A lead is stale when its newest score was computed against a different
--      audit than its newest one. That covers the first score (no score row at
--      all) and every re-audit, without a timestamp comparison that daylight
--      saving or a clock skew could get wrong.
--
--   3. An audit with no findings at all is not scored. That is exactly and only
--      the case where the CHECKER broke: every path through `judgeMeasurement`
--      that reached the business emits at least one row, including the passing
--      `no_website` row, and the error path deliberately emits nothing because
--      the failure says something about the checker and nothing about the
--      business. Scoring that as 0 would file "we could not look" under "we
--      looked and it was fine", and bury a real lead at the bottom of the list.
--      No score at all is the honest reading, and the row stays in this queue
--      so a re-audit picks it straight back up.
--
-- Config changes are deliberately NOT a staleness condition here. A view cannot
-- know which version the running build holds, and the operator already has the
-- right tool for it: changing a weight means rescoring the book, which is a
-- separate unconditional pass that costs nothing.
--
-- The business signals ride along because the scorer needs them and fetching
-- them separately would be a second round trip per pass for three columns.
-- ---------------------------------------------------------------------------
create view public.lead_score_queue
with (security_invoker = on) as
select
  l.id              as lead_id,
  l.latest_audit_id as audit_id,
  l.rating,
  l.user_rating_count,
  l.business_status
from public.leads l
  join public.lead_audits a on a.id = l.latest_audit_id
  left join public.lead_scores s on s.id = l.current_score_id
where l.deleted_at is null
  and a.psi_state not in ('pending', 'running')
  and exists (select 1 from public.lead_audit_findings f where f.audit_id = a.id)
  and s.audit_id is distinct from l.latest_audit_id;

comment on view public.lead_score_queue is
  'Leads whose newest audit has settled and has no score computed against it. The scorer''s work list; empty is the steady state.';

revoke all on public.lead_score_queue from anon, authenticated;

-- ---------------------------------------------------------------------------
-- lead_scoring_inputs — the same signals, for every live lead.
--
-- What a bulk rescore reads. It differs from the queue in exactly one way: it
-- does not care whether a score already exists, because after a weight changes
-- every score is wrong and the whole book is the work list.
--
-- It is a view rather than a filter on `leads` so that both passes agree on
-- what "a lead that can be scored" means — settled audit, not deleted. Two
-- definitions would eventually drift, and the day they did, the rescore would
-- quietly skip rows the incremental pass had been scoring all along.
--
-- The score already on the lead comes along so the pass can tell a tuning edit
-- that changed this lead from one that did not. Re-ranking is expected to be
-- run repeatedly over an afternoon of tuning, and appending five hundred
-- identical rows each time would bury the history that `lead_scores` is for.
-- ---------------------------------------------------------------------------
create view public.lead_scoring_inputs
with (security_invoker = on) as
select
  l.id              as lead_id,
  l.latest_audit_id as audit_id,
  l.rating,
  l.user_rating_count,
  l.business_status,
  l.current_score,
  s.config_version  as current_config_version
from public.leads l
  join public.lead_audits a on a.id = l.latest_audit_id
  left join public.lead_scores s on s.id = l.current_score_id
where l.deleted_at is null
  and a.psi_state not in ('pending', 'running')
  -- Same rule as the queue, and for the same reason: an audit that produced no
  -- judgements is the checker having broken, not a clean website.
  and exists (select 1 from public.lead_audit_findings f where f.audit_id = a.id);

comment on view public.lead_scoring_inputs is
  'Every live lead with a settled audit, plus the business signals scoring needs. The bulk rescore''s work list.';

revoke all on public.lead_scoring_inputs from anon, authenticated;


-- ============================================================================
-- 20260731090000_refresh_and_backoff.sql
-- ============================================================================

-- Lead Engine — keeping the snapshot honest, and surviving Google saying no.
--
-- Three things, all of them consequences of the product already working:
--
--   1. THE SNAPSHOT AGES. `leads.fetched_at` has carried the age of the Google
--      columns since the first migration and every surface states it, but
--      nothing has ever made it younger. A refresh path was promised in
--      PRODUCT.md and in the comment on that column; this is the storage for it.
--
--   2. A CHANGE IS NEWS, NOT A FINDING. What the refresh discovers — that a
--      business finally built a website, that its reviews doubled, that Google
--      now calls it permanently closed — is not a fault to be weighed by the
--      scorer. It is something that happened, and it belongs in the lead's
--      history next to the notes, with its own vocabulary. See lib/leads/changes.ts.
--
--   3. PAGESPEED SAYS NO UNDER LOAD. The free tier is rate-limited, and a bulk
--      re-audit is exactly the shape of traffic that trips it. Today a 429 lands
--      as `psi_state = 'failed'` and stays there for ever, so a whole batch can
--      be permanently marked unscoreable by a limit that lifted a minute later.
--      A rate limit is a "not now", and the schema has to be able to say so.

-- ---------------------------------------------------------------------------
-- First: confirm the scheduled jobs actually exist.
--
-- Three functions in earlier migrations are scheduled with cron.schedule() and
-- the compliance promise in PRODUCT.md rests on them running. A defined function
-- and a scheduled one look identical in a diff, so this asserts rather than
-- assumes: if pg_cron was not enabled when those migrations ran — the ordinary
-- way this fails, because the extension has to be available to the role running
-- them — the schedule call is a no-op nobody notices until a year of Google data
-- has quietly failed to expire.
--
-- cron.schedule() upserts by job name, so re-scheduling a job that is already
-- there is free and changes nothing.
-- ---------------------------------------------------------------------------
create extension if not exists pg_cron;

do $$
begin
  if not exists (select 1 from cron.job where jobname = 'expire-search-results') then
    raise warning 'expire-search-results was not scheduled; scheduling it now.';
    perform cron.schedule(
      'expire-search-results', '15 3 * * *',
      'select public.expire_search_results()'
    );
  end if;

  if not exists (select 1 from cron.job where jobname = 'purge-deleted-leads') then
    raise warning 'purge-deleted-leads was not scheduled; scheduling it now.';
    perform cron.schedule(
      'purge-deleted-leads', '45 3 * * *',
      'select public.purge_deleted_leads()'
    );
  end if;

  if not exists (select 1 from cron.job where jobname = 'expire-geocode-cache') then
    raise warning 'expire-geocode-cache was not scheduled; scheduling it now.';
    perform cron.schedule(
      'expire-geocode-cache', '30 3 * * *',
      'select public.expire_geocode_cache()'
    );
  end if;
end
$$;

-- The same question, answerable at any time without superuser and without
-- reading a migration file. `cron.job` is not readable by the app's role, so the
-- one thing worth knowing about it is lifted into a view that is.
create or replace view public.scheduled_jobs
with (security_invoker = off) as
select
  jobname   as name,
  schedule,
  command,
  active
from cron.job;

comment on view public.scheduled_jobs is
  'The database-side scheduled jobs, so the retention promises can be verified from the app rather than taken on trust. security_invoker is off deliberately: cron.job is superuser-only and this view is the sanctioned read of it.';

revoke all on public.scheduled_jobs from anon, authenticated;

-- ---------------------------------------------------------------------------
-- lead_audits — a rate limit is a "not now", not a verdict.
--
-- `psi_state` keeps its five values; what was missing is the ability to say
-- WHEN to try again and HOW MANY TIMES we already have. A 429 now puts the job
-- back to 'pending' with a retry time in the future, so the claim query simply
-- does not see it until then, and the audit keeps saying "waiting on PageSpeed"
-- — which is the truth — instead of "PageSpeed failed", which is not.
--
-- The attempt counter is what stops that being an infinite loop: past the
-- ceiling the job fails for real, with the last error on it.
-- ---------------------------------------------------------------------------
alter table public.lead_audits
  add column psi_attempts    smallint    not null default 0,
  add column psi_retry_after timestamptz;

comment on column public.lead_audits.psi_attempts is
  'How many times PageSpeed has been asked about this audit. Bounded so a permanently rate-limited key cannot loop.';
comment on column public.lead_audits.psi_retry_after is
  'Set when PageSpeed refused for a reason that will pass — a rate limit. The job stays pending and is invisible to the claim until this time.';

-- The claim reads (state, retry_after, audited_at). Rebuilt rather than added
-- to, so the index and the query it serves stay the same shape.
drop index if exists public.lead_audits_psi_queue_idx;
create index lead_audits_psi_queue_idx
  on public.lead_audits (psi_state, psi_retry_after nulls first, audited_at)
  where psi_state in ('pending', 'running');

-- ---------------------------------------------------------------------------
-- lead_refreshes — what changed, and what it changed from.
--
-- A row is written ONLY when something actually changed, or when the refresh
-- failed. "We asked Google and nothing had moved" is already recorded, on
-- `leads.fetched_at`, and writing thousands of empty rows a month to say it
-- again would bury the handful of rows that mean something.
--
-- Before and after are stored whole rather than as a list of column names, for
-- the same reason `lead_scores.factors` stores the arithmetic: two months later
-- the operator wants to read "94 reviews, now 128", and a change log that only
-- says "reviews changed" cannot tell him that.
-- ---------------------------------------------------------------------------
create table public.lead_refreshes (
  id            uuid        primary key default gen_random_uuid(),
  lead_id       uuid        not null references public.leads (id) on delete cascade,

  refreshed_at  timestamptz not null default now(),
  -- 'scheduled' or 'manual'. Text, not an enum: this is a provenance note, and
  -- the set will grow the first time a refresh is triggered some third way.
  source        text        not null default 'scheduled',

  -- The change vocabulary, as codes. Text for the same reason audit finding
  -- codes are text: the list belongs to the application, and adding to it must
  -- not require a migration.
  changes       text[]      not null default '{}',

  -- The volatile Google fields, either side of the refresh.
  before        jsonb,
  after         jsonb,

  -- Set when the refresh itself failed. Says nothing about the business.
  error         text,

  created_at    timestamptz not null default now(),

  constraint lead_refreshes_says_something
    check (array_length(changes, 1) is not null or error is not null)
);

comment on table public.lead_refreshes is
  'Append-only record of Google re-pulls that found something. One row per lead per change, with the values either side of it. Nothing is written when a refresh finds no movement — leads.fetched_at already records that we asked.';
comment on column public.lead_refreshes.changes is
  'Codes from lib/leads/changes.ts. Text, not an enum: the vocabulary belongs to the application.';

create index lead_refreshes_lead_id_refreshed_at_idx
  on public.lead_refreshes (lead_id, refreshed_at desc);
create index lead_refreshes_changes_idx
  on public.lead_refreshes using gin (changes);

-- ---------------------------------------------------------------------------
-- leads — the refresh's own bookkeeping.
--
-- `fetched_at` stays what it has always been: the age of the Google columns
-- beside it, and therefore the thing a staleness rule compares. The columns
-- added here are about the RUN, never about the business — the same split
-- `enrichment_error` and `lead_audits.error` already draw.
-- ---------------------------------------------------------------------------
alter table public.leads
  -- Set while a refresh holds this lead. A serverless invocation can vanish
  -- mid-run, so this is a claim with a timestamp on it and anything held too
  -- long is put back — exactly as enrichment_started_at works.
  add column refresh_started_at timestamptz,
  -- When Google last refused. Kept apart from fetched_at so a failing refresh
  -- can back off without making the snapshot look younger than it is.
  add column refresh_failed_at  timestamptz,
  add column refresh_error      text,
  -- Newest refresh that found something. Maintained by trigger, never written
  -- by the app, exactly like latest_audit_id.
  add column latest_refresh_id  uuid references public.lead_refreshes (id) on delete set null;

comment on column public.leads.refresh_started_at is
  'Claim marker for the refresh pass. Null when nothing holds this lead.';
comment on column public.leads.latest_refresh_id is
  'Newest lead_refreshes row for this lead. Denormalised by trigger; do not write directly.';

-- The refresh claim: oldest snapshot first, among live leads. Partial for the
-- same reason every other library index is.
create index leads_fetched_at_idx on public.leads (fetched_at)
  where deleted_at is null;
-- Putting back what a dead invocation is holding.
create index leads_refresh_started_at_idx on public.leads (refresh_started_at)
  where refresh_started_at is not null;

create or replace function public.refresh_lead_refresh_cache()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_lead_id uuid;
begin
  if tg_op = 'DELETE' then
    v_lead_id := old.lead_id;
  else
    v_lead_id := new.lead_id;
  end if;

  -- Newest row that actually recorded a change. A failed refresh is history
  -- worth keeping but it is not news about the business, and the mark on the
  -- row in the book must not read as one.
  update public.leads l
     set latest_refresh_id = r.id
    from (
      select id
        from public.lead_refreshes
       where lead_id = v_lead_id
         and array_length(changes, 1) is not null
       order by refreshed_at desc, id desc
       limit 1
    ) r
   where l.id = v_lead_id;

  if not found then
    update public.leads set latest_refresh_id = null where id = v_lead_id;
  end if;

  return null;
end;
$$;

create trigger lead_refreshes_refresh_cache
  after insert or update or delete on public.lead_refreshes
  for each row execute function public.refresh_lead_refresh_cache();

revoke all on function public.refresh_lead_refresh_cache() from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- leads_library — rebuilt so a change is a predicate, not a join.
--
-- `change_flags` is the exact counterpart of `audit_flags`: the newest change
-- set as an array, so "show me everyone who has built a website since I saved
-- them" is one overlap test on one relation, and the same filter machinery that
-- already serves the audit serves this with no new query shape.
--
-- Empty rather than synthetic-null-flagged, unlike audit_flags. "Never audited"
-- is a state the operator filters on; "nothing has changed" is the steady state
-- of every row in the book and is not worth a filter.
-- ---------------------------------------------------------------------------
drop view public.leads_library;

create view public.leads_library
with (security_invoker = on) as
select
  l.id,
  l.google_place_id,
  l.name,
  l.formatted_address,
  l.city,
  l.region,
  l.postal_code,
  l.country_code,
  l.phone,
  l.website,
  l.rating,
  l.user_rating_count,
  l.business_status,
  l.primary_type,
  l.google_maps_uri,
  l.fetched_at,

  l.status,
  l.follow_up_at,
  l.saved_at,
  l.deleted_at,
  l.current_score,
  l.scored_at,
  l.latest_audit_id,
  l.last_audited_at,
  l.enrichment_state,
  l.enrichment_error,
  l.refresh_error,

  -- The newest audit's measurements, lifted. Null throughout when a lead has
  -- never been audited, which is a distinct filter from any of the faults.
  a.website_status,
  a.dns_resolves,
  a.is_https,
  a.tls_valid,
  a.tls_expires_at,
  a.is_mobile_friendly,
  a.has_title,
  a.has_meta_description,
  a.has_favicon,
  a.is_table_layout,
  a.load_ms,
  a.copyright_year,
  a.platform,
  a.platform_version,
  a.presence_kind,
  a.psi_state,
  a.psi_performance,
  a.psi_lcp_ms,
  a.psi_cls,

  case
    when l.latest_audit_id is null then array['never_audited']::text[]
    else coalesce(a.failed_codes, '{}'::text[])
  end as audit_flags,

  coalesce(r.changes, '{}'::text[]) as change_flags,
  r.refreshed_at                    as changed_at,

  ll.list_ids,
  coalesce(n.note_count, 0) as note_count
from public.leads l
  left join public.lead_audits a on a.id = l.latest_audit_id
  left join public.lead_refreshes r on r.id = l.latest_refresh_id
  left join lateral (
    select coalesce(array_agg(x.list_id), '{}'::uuid[]) as list_ids
      from public.lead_lists x
     where x.lead_id = l.id
  ) ll on true
  left join lateral (
    select count(*) as note_count
      from public.lead_notes x
     where x.lead_id = l.id
  ) n on true;

comment on view public.leads_library is
  'Read model for the leads list: lead plus its newest audit measurements, its newest change set and its list membership, so every filter is a predicate on one relation.';
comment on column public.leads_library.audit_flags is
  'Every audit filter as one array: failed finding codes, or [never_audited] when the lead has no audit. Match with overlap.';
comment on column public.leads_library.change_flags is
  'The newest change set from the refresh pass, as codes. Empty when nothing has changed since the lead was saved.';

revoke all on public.leads_library from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Lockdown, extended to the new table. Same three layers as everything else:
-- the app's auth gate is the only authorization there is.
-- ---------------------------------------------------------------------------
alter table public.lead_refreshes enable row level security;

revoke all on public.lead_refreshes from anon, authenticated;


-- ============================================================================
-- 20260731110000_facets.sql
-- ============================================================================

-- Lead Engine — the filter bar's counts, computed where the rows are.
--
-- Every filter change in the library is a navigation, and every navigation
-- re-reads the facets: the cities the operator has saved from, the categories,
-- the lists and their live counts. That read has been a full scan shipped over
-- the wire — up to twenty thousand lead rows and twenty thousand list
-- memberships, fetched to Node, grouped in a loop, and thrown away to render
-- about thirty menu entries.
--
-- At the scale PRODUCT.md commits to — thousands of leads, revisited over
-- months — that is the wrong shape twice over. It is megabytes per click on the
-- surface the operator lives on, and it silently truncates: past the fetch
-- limit the counts quietly stop being true, with nothing saying so.
--
-- A GROUP BY belongs in the database. These views return one row per distinct
-- value, so the payload stops growing with the book.

-- ---------------------------------------------------------------------------
-- lead_facet_values — cities and categories present in the live library.
--
-- One view rather than two, with a `kind` discriminator, so the application
-- makes one round trip instead of two. They are read together, always, and
-- they have identical shape.
-- ---------------------------------------------------------------------------
create view public.lead_facet_values
with (security_invoker = on) as
select 'city' as kind, l.city as value, count(*) as count
  from public.leads l
 where l.deleted_at is null
   and l.city is not null
 group by l.city
union all
select 'category' as kind, l.primary_type as value, count(*) as count
  from public.leads l
 where l.deleted_at is null
   and l.primary_type is not null
 group by l.primary_type;

comment on view public.lead_facet_values is
  'Distinct cities and categories in the live library, with counts. One row per value, so the filter bar''s payload does not grow with the book.';

revoke all on public.lead_facet_values from anon, authenticated;

-- ---------------------------------------------------------------------------
-- lead_status_counts — the status facet.
--
-- Separate from the view above because its value is an enum rather than text,
-- and widening the union to a common type would mean casting the one column the
-- application wants to keep typed.
-- ---------------------------------------------------------------------------
create view public.lead_status_counts
with (security_invoker = on) as
select l.status, count(*) as count
  from public.leads l
 where l.deleted_at is null
 group by l.status;

comment on view public.lead_status_counts is
  'Live lead count per status, for the library''s status filter.';

revoke all on public.lead_status_counts from anon, authenticated;

-- ---------------------------------------------------------------------------
-- lead_list_counts — every list, with how many LIVE leads are in it.
--
-- A left join, not an inner one: a list the operator made and has not filled
-- yet must still appear in the menu, at zero. And the count is over live leads
-- only — a list holding forty deleted leads must not advertise forty.
-- ---------------------------------------------------------------------------
create view public.lead_list_counts
with (security_invoker = on) as
select
  li.id,
  li.name,
  count(l.id) as count
from public.lists li
  left join public.lead_lists ll on ll.list_id = li.id
  left join public.leads l on l.id = ll.lead_id and l.deleted_at is null
group by li.id, li.name;

comment on view public.lead_list_counts is
  'Every list with its live membership count. Lists with no live leads appear at zero rather than vanishing from the filter.';

revoke all on public.lead_list_counts from anon, authenticated;

-- The count above is a join per list; this is the index it reads.
create index if not exists lead_lists_list_id_idx on public.lead_lists (list_id);


-- ============================================================================
-- 20260731120000_imprint.sql
-- ============================================================================

-- Lead Engine — what the site says about itself, and who to write to.
--
-- Everything the audit measures today answers one question: does this website
-- WORK. Does it resolve, does it encrypt, does it fit on a phone, how fast does
-- the server hand it over. Every one of those is a fine observation and every
-- one of them is arguable on a call — "it is fast enough", "nobody uses a phone
-- for this". The operator's own note on it is that he sells against opinions.
--
-- This migration adds the other kind of observation: what the site SAYS. A
-- German commercial website is expected to carry an Impressum and a privacy
-- policy, and it is expected not to hand a visitor's IP address to Google
-- before the page has rendered. Those are checkable, and a business owner does
-- not argue about whether the page exists — he either has one or he does not.
--
-- Two halves, and the split between them is the one this schema has drawn since
-- the first migration:
--
--   1. NINE COLUMNS ON lead_audits — measurements. Where the Impressum was
--      found, what it names, what the homepage loads. Observations only; the
--      seven judgements they support live in lead_audit_findings and cost no
--      migration, which is the whole point of that table being open.
--
--   2. THREE COLUMNS ON leads — a postal address for the business, in the
--      email sense. Google sells a phone number and almost never an email, so
--      until now written outreach was not possible at all. An Impressum is the
--      one place on the open web where a company address reliably sits.
--
-- ON THE PERSON. §5 TMG requires an Impressum to name a natural person, and
-- every one we read will contain that name. It is deliberately NOT extracted
-- and NOT stored. Company facts are one thing and a named individual is
-- another; nothing in this product needs the second, so it does not keep it.
-- For the same reason the postal address is stored as a boolean and never as
-- text — whether the Impressum states an address is the finding, and the URL
-- beside it is how the operator checks the claim.

-- ---------------------------------------------------------------------------
-- lead_audits — nine observations.
--
-- Nullable throughout, and null means "not established" rather than "no", which
-- is the rule the checker already holds itself to. A site that never answered
-- has not told us it lacks an Impressum, and a boolean that cannot say so would
-- turn a network timeout into an accusation.
--
-- The state of the lookup itself — found, absent, error, skipped — deliberately
-- gets no column. It rides in `raw.imprint` along with the URLs that were tried
-- and what came back, the same way `raw.freeSubdomain` and `raw.datedMarkers`
-- carry observations that are worth recording and not worth a column. The rule
-- from the enrichment migration still decides it: a measurement earns a column
-- when it carries a value worth showing as proof.
-- ---------------------------------------------------------------------------
alter table public.lead_audits
  add column imprint_url           text,
  add column imprint_has_address   boolean,
  add column imprint_has_phone     boolean,
  add column imprint_has_email     boolean,
  add column imprint_has_vat_id    boolean,
  add column has_privacy_policy    boolean,
  add column loads_external_fonts  boolean,
  add column has_external_maps     boolean,
  add column contact_form_insecure boolean;

comment on column public.lead_audits.imprint_url is
  'Where the Impressum was found. Null when none was found, and also null when the lookup failed — raw.imprint.state is what tells those two apart, and only one of them is a finding.';
comment on column public.lead_audits.imprint_has_address is
  'Whether the Impressum states a street address with a house number and a postal town. A Postfach does not count: it is not an address a summons can be served at. The address itself is deliberately not stored.';
comment on column public.lead_audits.imprint_has_phone is
  'Whether the Impressum states a telephone number. Recorded because it is worth knowing, but it does not on its own make an Impressum incomplete — §5 TMG does not require one.';
comment on column public.lead_audits.imprint_has_email is
  'Whether the Impressum states an electronic address. True also for the obfuscated forms German imprints favour — info(at)firma.de — which satisfy the obligation even though nothing usable can be lifted out of them.';
comment on column public.lead_audits.imprint_has_vat_id is
  'Whether a VAT identification number is stated. A German Steuernummer is not one and does not count. Its absence is often perfectly lawful: §5 Abs. 1 Nr. 6 TMG asks for it only where one exists.';
comment on column public.lead_audits.has_privacy_policy is
  'Whether a privacy policy is LINKED from the pages that were read. Deliberately not "exists and is adequate" — the policy itself is never fetched, and the finding must not claim more than the measurement supports.';
comment on column public.lead_audits.loads_external_fonts is
  'Whether the page pulls webfonts from fonts.googleapis.com or fonts.gstatic.com, which transmits every visitor''s IP address to Google before anything has rendered. Self-hosted fonts do not match, which is the distinction that matters.';
comment on column public.lead_audits.has_external_maps is
  'Whether a Google Maps frame is present IN THE DELIVERED HTML. That is the measurable thing, and it is narrower than "loads without consent": a consent tool injects the frame from JavaScript after the visitor agrees, so it is absent here. The judgement withholds itself when a consent manager was detected.';
comment on column public.lead_audits.contact_form_insecure is
  'Whether a form that collects personal data sits on a page without TLS, or posts to an http:// address from an encrypted one. Null when the page had to be fetched over http because its certificate would not verify — that site is not unencrypted, it is misconfigured, and invalid_certificate already says so.';

-- ---------------------------------------------------------------------------
-- leads — an address to write to.
--
-- On `leads` rather than on the audit, because it is not a measurement of the
-- website's quality; it is a fact about the business that happens to have been
-- found on the website. It survives a re-audit, it belongs beside `phone`, and
-- it is what the CSV export is for.
--
-- Unlike `phone` and the rest of the Google block, this is not volatile data
-- under someone else's terms. We read it off the business's own page, and it is
-- the operator's to keep. `imprint_fetched_at` is here for the same reason
-- `fetched_at` is: a surface showing it must be able to say how old it is.
-- ---------------------------------------------------------------------------
alter table public.leads
  add column imprint_email      text,
  add column imprint_phone      text,
  add column imprint_fetched_at timestamptz;

comment on column public.leads.imprint_email is
  'A company email address read out of the Impressum. Role addresses are preferred over personal ones where a page offers both — better to write to, and less of a person''s data to hold. Never a reconstructed guess at an obfuscated address.';
comment on column public.leads.imprint_phone is
  'A telephone number read out of the Impressum. Kept separately from leads.phone, which comes from Google and is volatile under Google''s terms; this one is ours.';
comment on column public.leads.imprint_fetched_at is
  'When the two columns above were last read off the site. Written only when the lookup actually reached a verdict — a failed fetch leaves a good address alone rather than erasing it.';

-- The filter behind "show me everyone I can write to". Partial, because the
-- question is only ever asked of live leads that have an address at all, and a
-- full index would be mostly rows the query discards.
create index leads_imprint_email_idx
  on public.leads (id)
  where imprint_email is not null and deleted_at is null;

-- ---------------------------------------------------------------------------
-- leads_library — rebuilt for the three contact columns.
--
-- Only the three. The nine audit columns above are deliberately NOT lifted,
-- which breaks with how this view has treated every previous audit column, so
-- the reasoning belongs here rather than in a commit message:
--
--   - Nothing filters or sorts on them. The audit filters all run through
--     `audit_flags`, which the trigger on lead_audit_findings maintains, and a
--     new finding code joins that array without any help from this view.
--   - Nothing displays them from here. The lead detail reads the audit row
--     directly out of lead_audits, with its own column list.
--
-- So lifting them would add nine columns to every one of the hundred rows in a
-- library page, to be read by nobody. The three `leads` columns earn their
-- place because the has-an-email filter is a predicate on this relation and the
-- table and the export both read the values.
--
-- Dropped and recreated rather than replaced: Postgres cannot add a column to
-- the middle of a view in place, and a recreated view does not inherit its
-- grants — hence the revoke at the bottom, which is not optional.
-- ---------------------------------------------------------------------------
drop view public.leads_library;

create view public.leads_library
with (security_invoker = on) as
select
  l.id,
  l.google_place_id,
  l.name,
  l.formatted_address,
  l.city,
  l.region,
  l.postal_code,
  l.country_code,
  l.phone,
  l.website,
  l.rating,
  l.user_rating_count,
  l.business_status,
  l.primary_type,
  l.google_maps_uri,
  l.fetched_at,

  l.status,
  l.follow_up_at,
  l.saved_at,
  l.deleted_at,
  l.current_score,
  l.scored_at,
  l.latest_audit_id,
  l.last_audited_at,
  l.enrichment_state,
  l.enrichment_error,
  l.refresh_error,

  -- Read off the business's own Impressum, not off Google. This is what makes
  -- written outreach possible at all, so it travels with the row.
  l.imprint_email,
  l.imprint_phone,
  l.imprint_fetched_at,

  -- The newest audit's measurements, lifted. Null throughout when a lead has
  -- never been audited, which is a distinct filter from any of the faults.
  a.website_status,
  a.dns_resolves,
  a.is_https,
  a.tls_valid,
  a.tls_expires_at,
  a.is_mobile_friendly,
  a.has_title,
  a.has_meta_description,
  a.has_favicon,
  a.is_table_layout,
  a.load_ms,
  a.copyright_year,
  a.platform,
  a.platform_version,
  a.presence_kind,
  a.psi_state,
  a.psi_performance,
  a.psi_lcp_ms,
  a.psi_cls,

  case
    when l.latest_audit_id is null then array['never_audited']::text[]
    else coalesce(a.failed_codes, '{}'::text[])
  end as audit_flags,

  coalesce(r.changes, '{}'::text[]) as change_flags,
  r.refreshed_at                    as changed_at,

  ll.list_ids,
  coalesce(n.note_count, 0) as note_count
from public.leads l
  left join public.lead_audits a on a.id = l.latest_audit_id
  left join public.lead_refreshes r on r.id = l.latest_refresh_id
  left join lateral (
    select coalesce(array_agg(x.list_id), '{}'::uuid[]) as list_ids
      from public.lead_lists x
     where x.lead_id = l.id
  ) ll on true
  left join lateral (
    select count(*) as note_count
      from public.lead_notes x
     where x.lead_id = l.id
  ) n on true;

comment on view public.leads_library is
  'Read model for the leads list: lead plus its newest audit measurements, its newest change set and its list membership, so every filter is a predicate on one relation.';
comment on column public.leads_library.audit_flags is
  'Every audit filter as one array: failed finding codes, or [never_audited] when the lead has no audit. Match with overlap.';
comment on column public.leads_library.change_flags is
  'The newest change set from the refresh pass, as codes. Empty when nothing has changed since the lead was saved.';
comment on column public.leads_library.imprint_email is
  'The company email from the Impressum, carried so that "everyone I can write to" is a predicate here rather than a second query.';

revoke all on public.leads_library from anon, authenticated;

-- ---------------------------------------------------------------------------
-- Re-audit everything.
--
-- The Impressum cannot be read out of an audit that has already been written;
-- it is a page on the business's server that nobody has fetched yet. So every
-- existing audit has nine null columns and none of the seven new findings, and
-- a null column renders exactly like a clean one — "no Impressum problems
-- found" for a site nobody has looked at. That is the same quiet wrongness the
-- enrichment migration re-queued the whole book over, and it gets the same
-- answer.
--
-- `checker_version` is what makes the two states distinguishable afterwards:
-- audits stamped `measure-2` never looked, `measure-3` looked. The pass drains
-- the queue in slices the next time the library is opened, and old audit rows
-- are left alone — a re-audit has always been a new row, and the history is the
-- point of keeping them.
--
-- COST, because it is real and it is not money: this also re-runs the PageSpeed
-- stage for every lead. With GOOGLE_PAGESPEED_API_KEY set that is 25,000 free
-- calls a day and the book will drain in slices over a few days; without a key
-- it will meet the shared rate limit and reschedule itself through
-- psi_retry_after, which is the behaviour that limit was built for.
-- ---------------------------------------------------------------------------
update public.leads
   set enrichment_state      = 'queued',
       enrichment_queued_at  = now(),
       enrichment_started_at = null,
       enrichment_error      = null
 where deleted_at is null;
